"""Continuous same-world-point invariance, all24 preregistered directed pairs."""
from crop import *
def main():
    cfg=config();rows=[];out=R/'local_results/cross_view';out.mkdir(exist_ok=True)
    for origin,target in cfg['CORE_directed_pairs']+cfg['conditional_pairs']:
        s=native(origin);t=native(target);c=np.load(R/'local_results/crops'/(target+'.npz'));X=s['X'];uv,z=vis.project_camera(X,t['Kn'],t['T']);qp,zp=vis.project_camera(X,c['K_crop'],t['T']);q=affine_uv(uv,c['A']);err=np.linalg.norm(qp-q,axis=1);back=affine_uv(qp,c['A_inverse']);inv_err=np.linalg.norm(back-uv,axis=1)
        finite=np.isfinite(uv).all(1)&np.isfinite(qp).all(1);positive=finite&(z>0);native_inside=positive&(uv[:,0]>=-.5)&(uv[:,0]<639.5)&(uv[:,1]>=-.5)&(uv[:,1]<351.5);crop_inside=positive&(qp[:,0]>=-.5)&(qp[:,0]<319.5)&(qp[:,1]>=-.5)&(qp[:,1]<239.5)
        labels=np.full(len(X),-1,np.int8);crop_labels=np.full(len(X),-1,np.int8);target_depth=np.full(len(X),np.nan);crop_valid=np.zeros(len(X),bool);ii=np.flatnonzero(native_inside);p=np.floor(uv[ii]+.5).astype(int);labels[ii]=t['native_labels'][p[:,1],p[:,0]];target_depth[ii]=t['depth'][p[:,1],p[:,0]];jj=np.flatnonzero(crop_inside);p2=np.floor(qp[jj]+.5).astype(int);crop_labels[jj]=c['labels'][p2[:,1],p2[:,0]];crop_valid[jj]=c['valid'][p2[:,1],p2[:,0]]
        cad=np.full(len(X),np.inf);cad[ii],_=cast(ringscene(),uv[ii],t['Kn'],t['T']);hidden=np.isfinite(cad)&(z>cad+cfg['thresholds']['CAD_order_epsilon_mm']);original_support_domain=native_inside&(labels==1)&np.isfinite(target_depth)&(target_depth>0);lost=original_support_domain&~crop_valid
        row=dict(origin=origin,target=target,pair_type='CORE'if origin in CORE and target in CORE else 'CONDITIONAL_TRANSFORM_ONLY',source_point_denominator=len(X),analytic_projection_median_px=float(np.median(err)),analytic_projection_p95_px=float(np.quantile(err,.95)),analytic_projection_max_px=float(err.max()),inverse_mapping_max_native_px=float(inv_err.max()),finite_projection_N=int(finite.sum()),positive_camera_depth_N=int(positive.sum()),inside_native_target_N=int(native_inside.sum()),outside_native_target_N=int((~native_inside).sum()),inside_crop_target_N=int(crop_inside.sum()),OUT_OF_CROP_FIELD_N=int((~crop_inside).sum()),native_target_Polyp_N=int((labels==1).sum()),native_target_Ring_N=int((labels==2).sum()),native_target_BG_N=int((labels==0).sum()),CAD_OCCLUDED_N=int(hidden.sum()),original_target_legal_depth_N=int(original_support_domain.sum()),CROP_LOST_SUPPORT_N=int(lost.sum()),crop_target_Polyp_N=int(crop_valid.sum()),analytic_gate_pass=bool(finite.all()and err.max()<=cfg['thresholds']['analytic_target_projection_max_px']),pose_certified_by_this_test=False)
        rows.append(row);np.savez_compressed(out/(origin+'__'+target+'.npz'),source_native_id=s['native_id'],source_native_uv=s['native_uv'],X_world_mm=X,original_target_uv=uv,crop_target_uv=qp,affine_transformed_original_uv=q,inverse_crop_target_uv=back,analytic_projection_error_px=err,inverse_error_native_px=inv_err,target_axial_depth_mm=z,inside_native=native_inside,inside_crop=crop_inside,target_native_label=labels,target_crop_label=crop_labels,target_legal_original_depth=original_support_domain,crop_lost_support=lost,CAD_first_hit_mm=cad,CAD_occluded=hidden)
        print('PAIR',origin,'->',target,'max_px',err.max(),'N',len(X),'outside',row['OUT_OF_CROP_FIELD_N'],flush=True)
    table('CROSS_VIEW_PROJECTION_VALIDATION.csv',rows);save('config/CROSS_VIEW_GATE.json',dict(pair_count=len(rows),CORE_pair_count=6,all_analytic_pass=all(r['analytic_gate_pass']for r in rows),maximum_projection_error_px=max(r['analytic_projection_max_px']for r in rows),source_camera_accuracy_certified=False,all_source_point_denominators_retained=True))
if __name__=='__main__':main()
